  `asset_tracker_id` bigint unsigned NOT NULL,
  `device_id` bigint unsigned DEFAULT NULL,
  `occurred_at` datetime NOT NULL,
  `received_at` datetime NOT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `accuracy_m` smallint unsigned DEFAULT NULL,
  `speed_kph` decimal(8,2) DEFAULT NULL,
  `movement_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `battery_pct` smallint unsigned DEFAULT NULL,
  `power_source` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tamper_flag` tinyint(1) NOT NULL DEFAULT '0',
  `sos_flag` tinyint(1) NOT NULL DEFAULT '0',
  `vendor_payload_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vendor_metadata` json DEFAULT NULL,
  `consent_blocked` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `asset_telemetry_snapshots_vendor_payload_hash_unique` (`vendor_payload_hash`),
  KEY `asset_telemetry_snapshots_asset_id_occurred_at_index` (`asset_id`,`occurred_at`),
  KEY `asset_telemetry_snapshots_asset_tracker_id_occurred_at_index` (`asset_tracker_id`,`occurred_at`),
  KEY `asset_telemetry_snapshots_device_occurred_idx` (`device_id`,`occurred_at`),
  CONSTRAINT `asset_telemetry_snapshots_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `asset_telemetry_snapshots_asset_tracker_id_foreign` FOREIGN KEY (`asset_tracker_id`) REFERENCES `asset_trackers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `asset_telemetry_snapshots_device_id_foreign` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `asset_trackers`;
CREATE TABLE `asset_trackers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
