  `replacement_value` decimal(12,2) DEFAULT NULL,
  `depreciation_model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `depreciation_rate` decimal(6,3) DEFAULT NULL,
