  `wof_expires_at` date DEFAULT NULL,
  `cof_expires_at` date DEFAULT NULL,
  `fuel_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `odometer_km` decimal(10,1) DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `warranty_expires_at` date DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `risk_level` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requires_inspection` tinyint(1) NOT NULL DEFAULT '0',
  `inspection_due_at` date DEFAULT NULL,
  `requires_maintenance` tinyint(1) NOT NULL DEFAULT '0',
  `maintenance_due_at` date DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `has_wheelchair_ramp` tinyint(1) NOT NULL DEFAULT '0',
  `has_hoist` tinyint(1) NOT NULL DEFAULT '0',
  `has_child_seat_anchors` tinyint(1) NOT NULL DEFAULT '0',
  `has_medical_storage` tinyint(1) NOT NULL DEFAULT '0',
  `seating_capacity` int DEFAULT NULL,
  `accessibility_notes` text COLLATE utf8mb4_unicode_ci,
  `alert_config` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `assets_qr_token_unique` (`qr_token`),
  KEY `assets_client_id_foreign` (`client_id`),
  KEY `assets_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `assets_updated_by_user_id_foreign` (`updated_by_user_id`),
  KEY `assets_asset_tag_index` (`asset_tag`),
  KEY `assets_category_index` (`category`),
  KEY `assets_serial_number_index` (`serial_number`),
  KEY `assets_status_index` (`status`),
  KEY `assets_risk_level_index` (`risk_level`),
  KEY `assets_requires_inspection_index` (`requires_inspection`),
  KEY `assets_inspection_due_at_index` (`inspection_due_at`),
  KEY `assets_requires_maintenance_index` (`requires_maintenance`),
  KEY `assets_maintenance_due_at_index` (`maintenance_due_at`),
  KEY `idx_assets_qr_token` (`qr_token`),
  KEY `idx_assets_status` (`status`),
  KEY `idx_assets_site_status` (`site_id`,`status`),
  KEY `idx_assets_inspection_due` (`inspection_due_at`),
  KEY `idx_assets_maintenance_due` (`maintenance_due_at`),
  KEY `assets_asset_category_id_index` (`asset_category_id`),
  KEY `assets_home_site_id_foreign` (`home_site_id`),
  KEY `assets_primary_driver_user_id_foreign` (`primary_driver_user_id`),
  CONSTRAINT `assets_asset_category_id_foreign` FOREIGN KEY (`asset_category_id`) REFERENCES `asset_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `assets_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `assets_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `assets_home_site_id_foreign` FOREIGN KEY (`home_site_id`) REFERENCES `sites` (`id`) ON DELETE SET NULL,
  CONSTRAINT `assets_primary_driver_user_id_foreign` FOREIGN KEY (`primary_driver_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `assets_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE SET NULL,
  CONSTRAINT `assets_updated_by_user_id_foreign` FOREIGN KEY (`updated_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `audit_evidence_packs`;
CREATE TABLE `audit_evidence_packs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
