  KEY `billing_entries_client_id_status_index` (`client_id`,`status`),
  KEY `billing_entries_service_date_index` (`service_date`),
  KEY `billing_entries_organization_id_index` (`organization_id`),
  KEY `billing_entries_site_id_foreign` (`site_id`),
  CONSTRAINT `billing_entries_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `billing_entries_service_agreement_id_foreign` FOREIGN KEY (`service_agreement_id`) REFERENCES `service_agreements` (`id`) ON DELETE SET NULL,
  CONSTRAINT `billing_entries_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE SET NULL,
  CONSTRAINT `billing_entries_staff_id_foreign` FOREIGN KEY (`staff_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
