  CONSTRAINT `board_committees_chair_id_foreign` FOREIGN KEY (`chair_id`) REFERENCES `board_members` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

