  `committee_memberships` json DEFAULT NULL,
  `biography` text COLLATE utf8mb4_unicode_ci,
  `expertise_areas` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `succession_priority` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `succession_notes` text COLLATE utf8mb4_unicode_ci,
  `induction_completed_at` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `board_members_user_id_foreign` (`user_id`),
  KEY `board_members_board_role_is_active_index` (`board_role`,`is_active`),
  KEY `board_members_term_start_term_end_index` (`term_start`,`term_end`),
  CONSTRAINT `board_members_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `board_packs`;
CREATE TABLE `board_packs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
