  `watermark_text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CONFIDENTIAL - BOARD ONLY',
  `distributed_at` datetime DEFAULT NULL,
  `frozen_at` timestamp NULL DEFAULT NULL,
  `content_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
