  `distributed_to` json DEFAULT NULL,
  `download_tracking` json DEFAULT NULL,
  `read_tracking` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `board_packs_governance_meeting_id_unique` (`governance_meeting_id`),
  KEY `board_packs_generated_by_foreign` (`generated_by`),
  KEY `board_packs_generated_at_distributed_at_index` (`generated_at`,`distributed_at`),
  KEY `board_packs_dashboard_snapshot_id_foreign` (`dashboard_snapshot_id`),
  CONSTRAINT `board_packs_dashboard_snapshot_id_foreign` FOREIGN KEY (`dashboard_snapshot_id`) REFERENCES `dashboard_snapshots` (`id`) ON DELETE CASCADE,
  CONSTRAINT `board_packs_generated_by_foreign` FOREIGN KEY (`generated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `board_packs_governance_meeting_id_foreign` FOREIGN KEY (`governance_meeting_id`) REFERENCES `governance_meetings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `board_skills_matrix`;
CREATE TABLE `board_skills_matrix` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `board_member_id` bigint unsigned NOT NULL,
  `skill_category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
