  CONSTRAINT `break_glass_accesses_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `break_glass_accesses_closed_by_foreign` FOREIGN KEY (`closed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `break_glass_accesses_requested_by_foreign` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `budget_adjustments`;
CREATE TABLE `budget_adjustments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `budget_id` bigint unsigned NOT NULL,
  `budget_line_item_id` bigint unsigned NOT NULL,
  `adjustment_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `threshold_applies` tinyint(1) NOT NULL DEFAULT '0',
  `approval_resolution_id` bigint unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `proposed_by` bigint unsigned NOT NULL,
  `proposed_at` datetime NOT NULL,
  `review_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `budget_adjustments_budget_line_item_id_foreign` (`budget_line_item_id`),
  KEY `budget_adjustments_approval_resolution_id_foreign` (`approval_resolution_id`),
  KEY `budget_adjustments_approved_by_foreign` (`approved_by`),
  KEY `budget_adjustments_proposed_by_foreign` (`proposed_by`),
  KEY `budget_adjustments_budget_id_status_index` (`budget_id`,`status`),
  KEY `budget_adjustments_threshold_applies_status_index` (`threshold_applies`,`status`),
  CONSTRAINT `budget_adjustments_approval_resolution_id_foreign` FOREIGN KEY (`approval_resolution_id`) REFERENCES `resolutions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `budget_adjustments_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `budget_adjustments_budget_id_foreign` FOREIGN KEY (`budget_id`) REFERENCES `budgets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `budget_adjustments_budget_line_item_id_foreign` FOREIGN KEY (`budget_line_item_id`) REFERENCES `budget_line_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `budget_adjustments_proposed_by_foreign` FOREIGN KEY (`proposed_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `budget_line_items`;
CREATE TABLE `budget_line_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `budget_id` bigint unsigned NOT NULL,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subcategory` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gl_account_id` bigint unsigned DEFAULT NULL,
  `budget_amount` decimal(12,2) NOT NULL,
  `forecast_amount` decimal(12,2) DEFAULT NULL,
  `actual_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `variance_amount` decimal(12,2) DEFAULT NULL,
  `variance_pct` decimal(5,2) DEFAULT NULL,
  `variance_explanation` text COLLATE utf8mb4_unicode_ci,
  `variance_explained` tinyint(1) NOT NULL DEFAULT '0',
