  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `budget_line_items_budget_id_category_index` (`budget_id`,`category`),
  KEY `budget_line_items_budget_id_variance_pct_index` (`budget_id`,`variance_pct`),
  CONSTRAINT `budget_line_items_budget_id_foreign` FOREIGN KEY (`budget_id`) REFERENCES `budgets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `budgets`;
CREATE TABLE `budgets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `fiscal_year` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `total_budget` decimal(14,2) NOT NULL,
  `currency` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NZD',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'drafting',
  `proposed_by` bigint unsigned DEFAULT NULL,
  `proposed_at` datetime DEFAULT NULL,
  `approval_resolution_id` bigint unsigned DEFAULT NULL,
  `approved_by_board_at` datetime DEFAULT NULL,
  `version_number` int NOT NULL DEFAULT '1',
  `supersedes_budget_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `budgets_fiscal_year_version_number_unique` (`fiscal_year`,`version_number`),
  KEY `budgets_proposed_by_foreign` (`proposed_by`),
  KEY `budgets_approval_resolution_id_foreign` (`approval_resolution_id`),
  KEY `budgets_supersedes_budget_id_foreign` (`supersedes_budget_id`),
  KEY `budgets_created_by_foreign` (`created_by`),
  KEY `budgets_fiscal_year_status_index` (`fiscal_year`,`status`),
  CONSTRAINT `budgets_approval_resolution_id_foreign` FOREIGN KEY (`approval_resolution_id`) REFERENCES `resolutions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `budgets_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `budgets_proposed_by_foreign` FOREIGN KEY (`proposed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `budgets_supersedes_budget_id_foreign` FOREIGN KEY (`supersedes_budget_id`) REFERENCES `budgets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache`;
CREATE TABLE `cache` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
