  PRIMARY KEY (`id`),
  KEY `care_plan_goals_care_plan_id_foreign` (`care_plan_id`),
  KEY `care_plan_goals_client_id_foreign` (`client_id`),
  KEY `care_plan_goals_created_by_foreign` (`created_by`),
  KEY `care_plan_goals_organization_id_index` (`organization_id`),
  CONSTRAINT `care_plan_goals_care_plan_id_foreign` FOREIGN KEY (`care_plan_id`) REFERENCES `care_plans` (`id`) ON DELETE CASCADE,
