  `starts_at` date DEFAULT NULL,
  `ends_at` date DEFAULT NULL,
  `next_review_at` date DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `content` json DEFAULT NULL,
  `version` int NOT NULL DEFAULT '1',
  `parent_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `care_plans_client_id_foreign` (`client_id`),
  KEY `care_plans_reviewed_by_foreign` (`reviewed_by`),
  KEY `care_plans_created_by_foreign` (`created_by`),
  KEY `care_plans_parent_id_foreign` (`parent_id`),
  KEY `care_plans_organization_id_client_id_index` (`organization_id`,`client_id`),
  KEY `care_plans_status_index` (`status`),
  KEY `care_plans_next_review_at_index` (`next_review_at`),
  KEY `care_plans_organization_id_index` (`organization_id`),
  CONSTRAINT `care_plans_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `care_plans_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `care_plans_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `care_plans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `care_plans_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_care_plan_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'active',_utf8mb4'review',_utf8mb4'archived')))
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ceo_board_reports`;
CREATE TABLE `ceo_board_reports` (
