  CONSTRAINT `client_medication_administrations_correction_approved_by_foreign` FOREIGN KEY (`correction_approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `client_medication_administrations_medication_round_id_foreign` FOREIGN KEY (`medication_round_id`) REFERENCES `medication_rounds` (`id`) ON DELETE SET NULL,
  CONSTRAINT `client_medication_administrations_review_flagged_by_foreign` FOREIGN KEY (`review_flagged_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `client_medication_administrations_service_context_id_foreign` FOREIGN KEY (`service_context_id`) REFERENCES `service_contexts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `client_medication_administrations_shift_id_foreign` FOREIGN KEY (`shift_id`) REFERENCES `shifts` (`id`) ON DELETE SET NULL,
