  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `client_photos_uploaded_by_user_id_foreign` (`uploaded_by_user_id`),
  KEY `client_photos_approved_by_user_id_foreign` (`approved_by_user_id`),
