  KEY `dev_maint_device_completed_idx` (`device_id`,`completed_at`),
  CONSTRAINT `device_maintenance_records_device_id_foreign` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `device_maintenance_records_performed_by_user_id_foreign` FOREIGN KEY (`performed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `device_relationships`;
CREATE TABLE `device_relationships` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `parent_device_id` bigint unsigned NOT NULL,
  `child_device_id` bigint unsigned NOT NULL,
  `relationship_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `port` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dev_rel_pair_type_unique` (`parent_device_id`,`child_device_id`,`relationship_type`),
  KEY `dev_rel_child_idx` (`child_device_id`),
  CONSTRAINT `device_relationships_child_device_id_foreign` FOREIGN KEY (`child_device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `device_relationships_parent_device_id_foreign` FOREIGN KEY (`parent_device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `devices`;
CREATE TABLE `devices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `device_uid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `domain` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subcategory` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufacturer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serial_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mac_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `imei` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `asset_tag` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `firmware_version` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `next_service_due` date DEFAULT NULL,
  `ip_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `health_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
  `last_seen_at` timestamp NULL DEFAULT NULL,
  `last_signal_at` timestamp NULL DEFAULT NULL,
  `battery_level` tinyint unsigned DEFAULT NULL,
  `battery_updated_at` timestamp NULL DEFAULT NULL,
  `commissioned_at` date DEFAULT NULL,
  `warranty_expires_at` date DEFAULT NULL,
  `expected_lifespan_months` smallint unsigned DEFAULT NULL,
  `purchase_price` decimal(10,2) DEFAULT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `external_ref` json DEFAULT NULL,
  `config` json DEFAULT NULL,
  `meta` json DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `location_description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `legacy_location_hardware_id` bigint unsigned DEFAULT NULL,
  `legacy_asset_tracker_id` bigint unsigned DEFAULT NULL,
  `created_by_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `devices_device_uid_unique` (`device_uid`),
  KEY `devices_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `devices_tenant_domain_status_idx` (`tenant_id`,`domain`,`status`),
  KEY `devices_tenant_category_status_idx` (`tenant_id`,`category`,`status`),
  KEY `devices_tenant_provider_idx` (`tenant_id`,`provider`),
  KEY `devices_tenant_health_idx` (`tenant_id`,`health_status`),
  KEY `devices_serial_number_index` (`serial_number`),
  KEY `devices_mac_address_index` (`mac_address`),
  KEY `devices_imei_index` (`imei`),
  KEY `devices_legacy_location_hardware_id_index` (`legacy_location_hardware_id`),
  KEY `devices_legacy_asset_tracker_id_index` (`legacy_asset_tracker_id`),
  KEY `devices_tenant_id_index` (`tenant_id`),
  KEY `devices_next_service_due_idx` (`next_service_due`),
  CONSTRAINT `devices_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `emergency_drill_findings`;
CREATE TABLE `emergency_drill_findings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
