  `assigned_to` bigint unsigned DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `resolved_at` date DEFAULT NULL,
  `resolution_notes` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `emergency_drill_findings_emergency_drill_id_foreign` (`emergency_drill_id`),
  KEY `emergency_drill_findings_assigned_to_foreign` (`assigned_to`),
  KEY `emergency_drill_findings_created_by_foreign` (`created_by`),
  KEY `emergency_drill_findings_updated_by_foreign` (`updated_by`),
  KEY `emergency_drill_findings_status_index` (`status`),
  CONSTRAINT `emergency_drill_findings_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `emergency_drill_findings_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `emergency_drill_findings_emergency_drill_id_foreign` FOREIGN KEY (`emergency_drill_id`) REFERENCES `emergency_drills` (`id`) ON DELETE CASCADE,
  CONSTRAINT `emergency_drill_findings_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `emergency_drill_participants`;
CREATE TABLE `emergency_drill_participants` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `emergency_drill_id` bigint unsigned NOT NULL,
