  KEY `evidence_obligation_compliance_obligation_id_foreign` (`compliance_obligation_id`),
  KEY `evidence_obligation_linked_by_foreign` (`linked_by`),
  CONSTRAINT `evidence_obligation_compliance_obligation_id_foreign` FOREIGN KEY (`compliance_obligation_id`) REFERENCES `compliance_obligations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `evidence_obligation_evidence_library_id_foreign` FOREIGN KEY (`evidence_library_id`) REFERENCES `evidence_library` (`id`) ON DELETE CASCADE,
  CONSTRAINT `evidence_obligation_linked_by_foreign` FOREIGN KEY (`linked_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `evv_records`;
CREATE TABLE `evv_records` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `shift_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
