  `check_in_longitude` decimal(10,7) DEFAULT NULL,
  `check_out_latitude` decimal(10,7) DEFAULT NULL,
  `check_out_longitude` decimal(10,7) DEFAULT NULL,
  `check_in_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'gps',
  `check_out_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'gps',
  `verification_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `geofence_check_in` tinyint(1) DEFAULT NULL,
  `geofence_check_out` tinyint(1) DEFAULT NULL,
  `distance_from_site_in` decimal(8,2) DEFAULT NULL,
  `distance_from_site_out` decimal(8,2) DEFAULT NULL,
  `flagged_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `evv_records_user_id_foreign` (`user_id`),
  KEY `evv_records_client_id_foreign` (`client_id`),
  KEY `evv_records_shift_id_index` (`shift_id`),
  KEY `evv_records_verification_status_index` (`verification_status`),
  KEY `evv_records_organization_id_index` (`organization_id`),
  CONSTRAINT `evv_records_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `evv_records_shift_id_foreign` FOREIGN KEY (`shift_id`) REFERENCES `shifts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `evv_records_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `connection` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `queue` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `exception` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `family_notes`;
CREATE TABLE `family_notes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
