  `visibility` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'portal',
  `is_recurring` tinyint(1) NOT NULL DEFAULT '0',
  `recurrence_rule` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `family_notes_completed_by_foreign` (`completed_by`),
  KEY `family_notes_assigned_to_shift_id_foreign` (`assigned_to_shift_id`),
  KEY `family_notes_staff_responded_by_foreign` (`staff_responded_by`),
  KEY `family_notes_client_id_status_index` (`client_id`,`status`),
  KEY `family_notes_client_id_due_date_index` (`client_id`,`due_date`),
  KEY `family_notes_created_by_status_index` (`created_by`,`status`),
  CONSTRAINT `family_notes_assigned_to_shift_id_foreign` FOREIGN KEY (`assigned_to_shift_id`) REFERENCES `shifts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `family_notes_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `family_notes_completed_by_foreign` FOREIGN KEY (`completed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `family_notes_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `family_notes_staff_responded_by_foreign` FOREIGN KEY (`staff_responded_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `family_portal_settings`;
CREATE TABLE `family_portal_settings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
