  `notify_shift_completion` tinyint(1) NOT NULL DEFAULT '1',
  `notify_incident` tinyint(1) NOT NULL DEFAULT '1',
  `allow_family_photo_upload` tinyint(1) NOT NULL DEFAULT '0',
  `require_photo_approval` tinyint(1) NOT NULL DEFAULT '1',
  `show_location` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `family_portal_settings_client_id_unique` (`client_id`),
  KEY `family_portal_settings_organization_id_index` (`organization_id`),
