  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `provider` enum('xero','myob') COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Xero tenant ID or MYOB company file URI',
  `access_token` text COLLATE utf8mb4_unicode_ci,
  `refresh_token` text COLLATE utf8mb4_unicode_ci,
  `token_expires_at` datetime DEFAULT NULL,
  `last_sync_at` datetime DEFAULT NULL,
  `last_sync_status` enum('success','failed','pending') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `sync_direction` enum('push','pull','bidirectional') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bidirectional',
  `account_mapping` json DEFAULT NULL COMMENT 'Maps local account IDs to external IDs',
  `tax_mapping` json DEFAULT NULL COMMENT 'Maps local tax rate IDs to external tax type IDs',
  `settings` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fin_acct_integ_org_provider_unique` (`organization_id`,`provider`),
  KEY `fin_accounting_integrations_created_by_foreign` (`created_by`),
  KEY `fin_accounting_integrations_organization_id_index` (`organization_id`),
  CONSTRAINT `fin_accounting_integrations_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_accounts`;
CREATE TABLE `fin_accounts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('asset','liability','equity','revenue','expense') COLLATE utf8mb4_unicode_ci NOT NULL,
  `sub_type` enum('bank','accounts_receivable','accounts_payable','fixed_asset','accumulated_depreciation','current_asset','current_liability','long_term_liability','equity','revenue','cost_of_sales','expense','other') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_id` bigint unsigned DEFAULT NULL,
  `funding_stream_id` bigint unsigned DEFAULT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `opening_balance` decimal(14,2) NOT NULL DEFAULT '0.00',
  `description` text COLLATE utf8mb4_unicode_ci,
  `xero_account_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `myob_account_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gst_applicable` tinyint(1) NOT NULL DEFAULT '0',
  `default_tax_rate_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fin_accounts_organization_id_code_unique` (`organization_id`,`code`),
  KEY `fin_accounts_parent_id_foreign` (`parent_id`),
  KEY `fin_accounts_created_by_foreign` (`created_by`),
  KEY `fin_accounts_organization_id_type_is_active_index` (`organization_id`,`type`,`is_active`),
  KEY `fin_accounts_organization_id_index` (`organization_id`),
  CONSTRAINT `fin_accounts_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fin_accounts_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `fin_accounts` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_audit_exports`;
CREATE TABLE `fin_audit_exports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `export_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `period_from` date NOT NULL,
  `period_to` date NOT NULL,
  `include_journals` tinyint(1) NOT NULL DEFAULT '1',
  `include_bank_reconciliations` tinyint(1) NOT NULL DEFAULT '1',
  `include_ap` tinyint(1) NOT NULL DEFAULT '1',
  `include_ar` tinyint(1) NOT NULL DEFAULT '1',
  `include_gst` tinyint(1) NOT NULL DEFAULT '1',
  `include_fixed_assets` tinyint(1) NOT NULL DEFAULT '1',
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_size_bytes` bigint unsigned DEFAULT NULL,
  `status` enum('pending','generating','completed','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `generated_at` datetime DEFAULT NULL,
  `downloaded_at` datetime DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fin_audit_exports_created_by_foreign` (`created_by`),
  KEY `fin_audit_exports_organization_id_index` (`organization_id`),
  CONSTRAINT `fin_audit_exports_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_bank_accounts`;
CREATE TABLE `fin_bank_accounts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bank_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_number` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_type` enum('cheque','savings','trust') COLLATE utf8mb4_unicode_ci NOT NULL,
