  `status` enum('success','failed','partial') COLLATE utf8mb4_unicode_ci NOT NULL,
  `transactions_fetched` int unsigned NOT NULL DEFAULT '0',
  `transactions_imported` int unsigned NOT NULL DEFAULT '0',
  `transactions_skipped` int unsigned NOT NULL DEFAULT '0',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `duration_ms` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fin_bank_feed_logs_bank_feed_id_synced_at_index` (`bank_feed_id`,`synced_at`),
  CONSTRAINT `fin_bank_feed_logs_bank_feed_id_foreign` FOREIGN KEY (`bank_feed_id`) REFERENCES `fin_bank_feeds` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_bank_feeds`;
CREATE TABLE `fin_bank_feeds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
