  KEY `fin_bank_reconciliations_completed_by_foreign` (`completed_by`),
  KEY `fin_bank_reconciliations_created_by_foreign` (`created_by`),
  KEY `fin_bank_reconciliations_organization_id_bank_account_id_index` (`organization_id`,`bank_account_id`),
  KEY `fin_bank_reconciliations_organization_id_index` (`organization_id`),
  CONSTRAINT `fin_bank_reconciliations_bank_account_id_foreign` FOREIGN KEY (`bank_account_id`) REFERENCES `fin_bank_accounts` (`id`),
  CONSTRAINT `fin_bank_reconciliations_completed_by_foreign` FOREIGN KEY (`completed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fin_bank_reconciliations_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_bank_transactions`;
CREATE TABLE `fin_bank_transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `bank_account_id` bigint unsigned NOT NULL,
  `transaction_date` date NOT NULL,
  `amount` decimal(14,2) NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payee` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` enum('manual','import','feed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `reconciliation_id` bigint unsigned DEFAULT NULL,
  `matched_journal_line_id` bigint unsigned DEFAULT NULL,
  `bank_feed_id` bigint unsigned DEFAULT NULL,
  `external_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_from_feed` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('unreconciled','matched','reconciled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unreconciled',
  `currency_id` bigint unsigned DEFAULT NULL,
  `exchange_rate` decimal(14,6) DEFAULT NULL,
  `base_amount` decimal(14,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fin_bank_txn_acct_ext_unique` (`bank_account_id`,`external_id`),
  KEY `fin_bank_transactions_bank_account_id_transaction_date_index` (`bank_account_id`,`transaction_date`),
  KEY `fin_bank_transactions_organization_id_status_index` (`organization_id`,`status`),
  KEY `fin_bank_transactions_organization_id_index` (`organization_id`),
  KEY `fin_bank_transactions_currency_id_foreign` (`currency_id`),
  KEY `fin_bank_transactions_bank_feed_id_foreign` (`bank_feed_id`),
  CONSTRAINT `fin_bank_transactions_bank_account_id_foreign` FOREIGN KEY (`bank_account_id`) REFERENCES `fin_bank_accounts` (`id`),
  CONSTRAINT `fin_bank_transactions_bank_feed_id_foreign` FOREIGN KEY (`bank_feed_id`) REFERENCES `fin_bank_feeds` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fin_bank_transactions_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `fin_currencies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_bill_lines`;
CREATE TABLE `fin_bill_lines` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
