  `subtotal` decimal(14,2) NOT NULL DEFAULT '0.00',
  `gst_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `amount_paid` decimal(14,2) NOT NULL DEFAULT '0.00',
  `approved_by` bigint unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `journal_id` bigint unsigned DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `xero_invoice_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `myob_invoice_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `currency_id` bigint unsigned DEFAULT NULL,
  `exchange_rate` decimal(14,6) DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fin_bills_organization_id_bill_number_unique` (`organization_id`,`bill_number`),
  KEY `fin_bills_approved_by_foreign` (`approved_by`),
  KEY `fin_bills_created_by_foreign` (`created_by`),
  KEY `fin_bills_organization_id_status_index` (`organization_id`,`status`),
  KEY `fin_bills_organization_id_due_date_index` (`organization_id`,`due_date`),
  KEY `fin_bills_vendor_id_index` (`vendor_id`),
  KEY `fin_bills_organization_id_index` (`organization_id`),
  KEY `fin_bills_currency_id_foreign` (`currency_id`),
  CONSTRAINT `fin_bills_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fin_bills_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fin_bills_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `fin_currencies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fin_bills_vendor_id_foreign` FOREIGN KEY (`vendor_id`) REFERENCES `fin_vendors` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fin_cash_flow_forecasts`;
