DROP TABLE IF EXISTS `fleet_service_schedules`;
CREATE TABLE `fleet_service_schedules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned DEFAULT NULL,
  `asset_id` bigint unsigned DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `interval_km` int unsigned DEFAULT NULL,
  `interval_days` int unsigned DEFAULT NULL,
  `last_completed_at` datetime DEFAULT NULL,
  `last_completed_km` decimal(10,1) DEFAULT NULL,
  `next_due_at` datetime DEFAULT NULL,
  `next_due_km` decimal(10,1) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fleet_service_schedules_asset_id_foreign` (`asset_id`),
  CONSTRAINT `fleet_service_schedules_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_shift_handovers`;
CREATE TABLE `fleet_shift_handovers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned DEFAULT NULL,
  `asset_id` bigint unsigned NOT NULL,
  `outgoing_user_id` bigint unsigned NOT NULL,
  `incoming_user_id` bigint unsigned DEFAULT NULL,
  `odometer_km` int DEFAULT NULL,
  `fuel_level` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exterior_condition` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `interior_condition` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `keys_present` tinyint(1) NOT NULL DEFAULT '1',
  `documents_present` tinyint(1) NOT NULL DEFAULT '1',
  `first_aid_kit` tinyint(1) NOT NULL DEFAULT '1',
  `fire_extinguisher` tinyint(1) NOT NULL DEFAULT '1',
  `damage_notes` json DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_acceptance',
  `handed_over_at` timestamp NOT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fleet_shift_handovers_asset_id_foreign` (`asset_id`),
  KEY `fleet_shift_handovers_outgoing_user_id_foreign` (`outgoing_user_id`),
  KEY `fleet_shift_handovers_incoming_user_id_foreign` (`incoming_user_id`),
  KEY `fleet_shift_handovers_tenant_id_index` (`tenant_id`),
  CONSTRAINT `fleet_shift_handovers_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`),
  CONSTRAINT `fleet_shift_handovers_incoming_user_id_foreign` FOREIGN KEY (`incoming_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fleet_shift_handovers_outgoing_user_id_foreign` FOREIGN KEY (`outgoing_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_signal_outbox`;
CREATE TABLE `fleet_signal_outbox` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `fleet_signal_id` bigint unsigned NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `attempts` int unsigned NOT NULL DEFAULT '0',
  `last_attempt_at` datetime DEFAULT NULL,
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fleet_signal_outbox_fleet_signal_id_foreign` (`fleet_signal_id`),
  KEY `fleet_signal_outbox_status_last_attempt_at_index` (`status`,`last_attempt_at`),
  CONSTRAINT `fleet_signal_outbox_fleet_signal_id_foreign` FOREIGN KEY (`fleet_signal_id`) REFERENCES `fleet_signals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_signals`;
CREATE TABLE `fleet_signals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` bigint unsigned NOT NULL,
  `asset_tracker_id` bigint unsigned DEFAULT NULL,
  `device_id` bigint unsigned DEFAULT NULL,
  `geofence_id` bigint unsigned DEFAULT NULL,
  `trip_id` bigint unsigned DEFAULT NULL,
  `driver_session_id` bigint unsigned DEFAULT NULL,
  `signal_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity_hint` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'low',
  `occurred_at` datetime NOT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fleet_signals_idempotency_key_unique` (`idempotency_key`),
  KEY `fleet_signals_asset_tracker_id_foreign` (`asset_tracker_id`),
  KEY `fleet_signals_geofence_id_foreign` (`geofence_id`),
  KEY `fleet_signals_trip_id_foreign` (`trip_id`),
  KEY `fleet_signals_driver_session_id_foreign` (`driver_session_id`),
  KEY `fleet_signals_asset_id_occurred_at_index` (`asset_id`,`occurred_at`),
  KEY `fleet_signals_signal_type_occurred_at_index` (`signal_type`,`occurred_at`),
  KEY `fleet_signals_device_occurred_idx` (`device_id`,`occurred_at`),
  CONSTRAINT `fleet_signals_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fleet_signals_asset_tracker_id_foreign` FOREIGN KEY (`asset_tracker_id`) REFERENCES `asset_trackers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_signals_device_id_foreign` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_signals_driver_session_id_foreign` FOREIGN KEY (`driver_session_id`) REFERENCES `fleet_driver_sessions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_signals_geofence_id_foreign` FOREIGN KEY (`geofence_id`) REFERENCES `asset_geofences` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_signals_trip_id_foreign` FOREIGN KEY (`trip_id`) REFERENCES `fleet_trips` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_telemetry_events`;
CREATE TABLE `fleet_telemetry_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` bigint unsigned NOT NULL,
  `asset_tracker_id` bigint unsigned NOT NULL,
  `device_id` bigint unsigned DEFAULT NULL,
  `vendor` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vendor_message_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occurred_at` datetime NOT NULL,
  `received_at` datetime NOT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `accuracy_m` smallint unsigned DEFAULT NULL,
  `speed_kph` decimal(8,2) DEFAULT NULL,
  `heading_deg` smallint unsigned DEFAULT NULL,
  `altitude_m` int DEFAULT NULL,
  `ignition` tinyint(1) DEFAULT NULL,
  `motion_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `battery_pct` smallint unsigned DEFAULT NULL,
  `external_power` tinyint(1) DEFAULT NULL,
  `odometer_km` decimal(10,3) DEFAULT NULL,
  `event_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `raw_payload` json DEFAULT NULL,
  `consent_blocked` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fleet_telemetry_events_idempotency_key_unique` (`idempotency_key`),
  KEY `fleet_telemetry_events_asset_id_occurred_at_index` (`asset_id`,`occurred_at`),
  KEY `fleet_telemetry_events_asset_tracker_id_occurred_at_index` (`asset_tracker_id`,`occurred_at`),
  KEY `fleet_telemetry_events_event_type_occurred_at_index` (`event_type`,`occurred_at`),
  KEY `fleet_telemetry_events_device_occurred_idx` (`device_id`,`occurred_at`),
  CONSTRAINT `fleet_telemetry_events_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fleet_telemetry_events_asset_tracker_id_foreign` FOREIGN KEY (`asset_tracker_id`) REFERENCES `asset_trackers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fleet_telemetry_events_device_id_foreign` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_telemetry_ingest_batches`;
CREATE TABLE `fleet_telemetry_ingest_batches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `vendor` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `received_at` datetime NOT NULL,
  `record_count` int unsigned NOT NULL DEFAULT '0',
  `checksum` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'received',
  `errors_json` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fleet_telemetry_ingest_batches_vendor_received_at_index` (`vendor`,`received_at`),
  KEY `fleet_telemetry_ingest_batches_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_trip_segments`;
CREATE TABLE `fleet_trip_segments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `fleet_trip_id` bigint unsigned NOT NULL,
  `seq` int unsigned NOT NULL,
  `started_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL,
  `distance_km` decimal(10,3) NOT NULL DEFAULT '0.000',
  `duration_s` int unsigned NOT NULL DEFAULT '0',
  `polyline` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fleet_trip_segments_fleet_trip_id_seq_unique` (`fleet_trip_id`,`seq`),
  CONSTRAINT `fleet_trip_segments_fleet_trip_id_foreign` FOREIGN KEY (`fleet_trip_id`) REFERENCES `fleet_trips` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_trips`;
CREATE TABLE `fleet_trips` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` bigint unsigned NOT NULL,
  `driver_session_id` bigint unsigned DEFAULT NULL,
  `started_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL,
  `start_latitude` decimal(10,7) DEFAULT NULL,
  `start_longitude` decimal(10,7) DEFAULT NULL,
  `start_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `end_latitude` decimal(10,7) DEFAULT NULL,
  `end_longitude` decimal(10,7) DEFAULT NULL,
  `end_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reverse_geocoded_at` timestamp NULL DEFAULT NULL,
  `distance_km` decimal(10,3) NOT NULL DEFAULT '0.000',
  `duration_s` int unsigned NOT NULL DEFAULT '0',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `consent_blocked` tinyint(1) NOT NULL DEFAULT '0',
  `is_personal` tinyint(1) NOT NULL DEFAULT '0',
  `marked_personal_by` bigint unsigned DEFAULT NULL,
  `marked_personal_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fleet_trips_driver_session_id_foreign` (`driver_session_id`),
  KEY `fleet_trips_asset_id_started_at_index` (`asset_id`,`started_at`),
  KEY `fleet_trips_status_index` (`status`),
  KEY `fleet_trips_marked_personal_by_foreign` (`marked_personal_by`),
  CONSTRAINT `fleet_trips_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fleet_trips_driver_session_id_foreign` FOREIGN KEY (`driver_session_id`) REFERENCES `fleet_driver_sessions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_trips_marked_personal_by_foreign` FOREIGN KEY (`marked_personal_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_vehicle_bookings`;
CREATE TABLE `fleet_vehicle_bookings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned DEFAULT NULL,
  `asset_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `approved_by_user_id` bigint unsigned DEFAULT NULL,
  `purpose` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `passengers` int DEFAULT NULL,
  `pickup_site_id` bigint unsigned DEFAULT NULL,
  `return_site_id` bigint unsigned DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `review_required` tinyint(1) NOT NULL DEFAULT '0',
  `review_reason` text COLLATE utf8mb4_unicode_ci,
  `review_flagged_at` timestamp NULL DEFAULT NULL,
  `review_flagged_by` bigint unsigned DEFAULT NULL,
  `pre_trip_inspection_id` bigint unsigned DEFAULT NULL,
  `post_trip_inspection_id` bigint unsigned DEFAULT NULL,
  `destination` text COLLATE utf8mb4_unicode_ci,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `checked_out_at` datetime DEFAULT NULL,
  `returned_at` datetime DEFAULT NULL,
  `checked_out_by` bigint unsigned DEFAULT NULL,
  `returned_by` bigint unsigned DEFAULT NULL,
  `odometer_out` decimal(10,1) DEFAULT NULL,
  `odometer_in` decimal(10,1) DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `return_notes` text COLLATE utf8mb4_unicode_ci,
  `condition_on_return` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fleet_vehicle_bookings_approved_by_user_id_foreign` (`approved_by_user_id`),
  KEY `fleet_vehicle_bookings_checked_out_by_foreign` (`checked_out_by`),
  KEY `fleet_vehicle_bookings_returned_by_foreign` (`returned_by`),
  KEY `fleet_vehicle_bookings_asset_id_starts_at_ends_at_index` (`asset_id`,`starts_at`,`ends_at`),
  KEY `fleet_vehicle_bookings_user_id_status_index` (`user_id`,`status`),
  KEY `fleet_vehicle_bookings_status_index` (`status`),
  KEY `fleet_vehicle_bookings_review_flagged_by_foreign` (`review_flagged_by`),
  CONSTRAINT `fleet_vehicle_bookings_approved_by_user_id_foreign` FOREIGN KEY (`approved_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_vehicle_bookings_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fleet_vehicle_bookings_checked_out_by_foreign` FOREIGN KEY (`checked_out_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_vehicle_bookings_returned_by_foreign` FOREIGN KEY (`returned_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_vehicle_bookings_review_flagged_by_foreign` FOREIGN KEY (`review_flagged_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_vehicle_bookings_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_vehicle_state_snapshots`;
CREATE TABLE `fleet_vehicle_state_snapshots` (
  `asset_id` bigint unsigned NOT NULL,
  `last_event_id` bigint unsigned DEFAULT NULL,
  `last_trip_id` bigint unsigned DEFAULT NULL,
  `last_seen_at` datetime DEFAULT NULL,
  `last_moving_at` datetime DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `speed_kph` decimal(8,2) DEFAULT NULL,
  `heading_deg` smallint unsigned DEFAULT NULL,
  `ignition` tinyint(1) DEFAULT NULL,
  `motion_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `battery_pct` smallint unsigned DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'offline',
  `consent_blocked` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`asset_id`),
  KEY `fleet_vehicle_state_snapshots_last_event_id_foreign` (`last_event_id`),
  KEY `fleet_vehicle_state_snapshots_last_trip_id_foreign` (`last_trip_id`),
  KEY `fleet_vehicle_state_snapshots_status_last_seen_at_index` (`status`,`last_seen_at`),
  CONSTRAINT `fleet_vehicle_state_snapshots_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fleet_vehicle_state_snapshots_last_event_id_foreign` FOREIGN KEY (`last_event_id`) REFERENCES `fleet_telemetry_events` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_vehicle_state_snapshots_last_trip_id_foreign` FOREIGN KEY (`last_trip_id`) REFERENCES `fleet_trips` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `fleet_work_orders`;
CREATE TABLE `fleet_work_orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned DEFAULT NULL,
  `asset_id` bigint unsigned NOT NULL,
  `reported_by_user_id` bigint unsigned NOT NULL,
  `assigned_to_user_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `priority` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `due_at` datetime DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `estimated_cost` decimal(10,2) DEFAULT NULL,
  `actual_cost` decimal(10,2) DEFAULT NULL,
  `completion_notes` text COLLATE utf8mb4_unicode_ci,
  `journal_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fleet_work_orders_reported_by_user_id_foreign` (`reported_by_user_id`),
  KEY `fleet_work_orders_assigned_to_user_id_foreign` (`assigned_to_user_id`),
  KEY `fleet_work_orders_asset_id_status_index` (`asset_id`,`status`),
  KEY `fleet_work_orders_status_priority_index` (`status`,`priority`),
  KEY `fleet_work_orders_journal_id_foreign` (`journal_id`),
  CONSTRAINT `fleet_work_orders_asset_id_foreign` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fleet_work_orders_assigned_to_user_id_foreign` FOREIGN KEY (`assigned_to_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_work_orders_journal_id_foreign` FOREIGN KEY (`journal_id`) REFERENCES `fin_journals` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fleet_work_orders_reported_by_user_id_foreign` FOREIGN KEY (`reported_by_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `funding_claim_items`;
CREATE TABLE `funding_claim_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `funding_claim_id` bigint unsigned NOT NULL,
  `service_agreement_line_item_id` bigint unsigned DEFAULT NULL,
  `shift_id` bigint unsigned DEFAULT NULL,
  `timesheet_id` bigint unsigned DEFAULT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` decimal(10,2) NOT NULL,
  `unit_price` decimal(8,2) NOT NULL,
  `total_amount` decimal(12,2) NOT NULL,
  `service_date` date NOT NULL,
  `ndis_line_item_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `funding_claim_items_funding_claim_id_foreign` (`funding_claim_id`),
  KEY `fci_sali_foreign` (`service_agreement_line_item_id`),
  KEY `funding_claim_items_organization_id_index` (`organization_id`),
  CONSTRAINT `fci_sali_foreign` FOREIGN KEY (`service_agreement_line_item_id`) REFERENCES `service_agreement_line_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `funding_claim_items_funding_claim_id_foreign` FOREIGN KEY (`funding_claim_id`) REFERENCES `funding_claims` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `funding_claims`;
CREATE TABLE `funding_claims` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `service_agreement_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `claim_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `total_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `submitted_at` datetime DEFAULT NULL,
  `submitted_by` bigint unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `journal_id` bigint unsigned DEFAULT NULL,
  `gl_posted_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `funding_claims_service_agreement_id_foreign` (`service_agreement_id`),
  KEY `funding_claims_client_id_foreign` (`client_id`),
  KEY `funding_claims_submitted_by_foreign` (`submitted_by`),
  KEY `funding_claims_approved_by_foreign` (`approved_by`),
  KEY `funding_claims_organization_id_index` (`organization_id`),
  CONSTRAINT `funding_claims_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `funding_claims_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `funding_claims_service_agreement_id_foreign` FOREIGN KEY (`service_agreement_id`) REFERENCES `service_agreements` (`id`) ON DELETE CASCADE,
  CONSTRAINT `funding_claims_submitted_by_foreign` FOREIGN KEY (`submitted_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `geofence_zones`;
CREATE TABLE `geofence_zones` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `site_id` bigint unsigned DEFAULT NULL,
  `client_id` bigint unsigned DEFAULT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `radius_meters` int unsigned NOT NULL DEFAULT '200',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `geofence_zones_client_id_foreign` (`client_id`),
  KEY `geofence_zones_organization_id_index` (`organization_id`),
  CONSTRAINT `geofence_zones_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `governance_audit_log`;
CREATE TABLE `governance_audit_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
