  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `governance_feedback_escalations_assigned_to_foreign` (`assigned_to`),
  KEY `governance_feedback_escalations_escalated_by_foreign` (`escalated_by`),
  KEY `governance_feedback_escalations_resolved_by_foreign` (`resolved_by`),
  KEY `governance_feedback_escalations_status_severity_index` (`status`,`severity`),
  CONSTRAINT `governance_feedback_escalations_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`),
  CONSTRAINT `governance_feedback_escalations_escalated_by_foreign` FOREIGN KEY (`escalated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `governance_feedback_escalations_resolved_by_foreign` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `governance_meetings`;
CREATE TABLE `governance_meetings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `meeting_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `board_committee_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scheduled_at` datetime NOT NULL,
  `duration_minutes` int NOT NULL DEFAULT '120',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `virtual_link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `quorum_required` int NOT NULL DEFAULT '50',
  `quorum_met` tinyint(1) NOT NULL DEFAULT '0',
  `chair_id` bigint unsigned DEFAULT NULL,
  `secretary_id` bigint unsigned DEFAULT NULL,
  `pack_distributed_at` datetime DEFAULT NULL,
  `minutes_approved_at` datetime DEFAULT NULL,
  `minutes_approved_by` bigint unsigned DEFAULT NULL,
  `minutes_signed_at` datetime DEFAULT NULL,
  `minutes_signed_by` bigint unsigned DEFAULT NULL,
  `locked_at` timestamp NULL DEFAULT NULL,
  `locked_by` bigint unsigned DEFAULT NULL,
  `recurring_schedule_id` bigint unsigned DEFAULT NULL,
  `rsvp_deadline` date DEFAULT NULL,
  `preread_deadline` date DEFAULT NULL,
  `ceo_report_deadline` date DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `governance_meetings_board_committee_id_foreign` (`board_committee_id`),
  KEY `governance_meetings_chair_id_foreign` (`chair_id`),
  KEY `governance_meetings_secretary_id_foreign` (`secretary_id`),
  KEY `governance_meetings_minutes_approved_by_foreign` (`minutes_approved_by`),
  KEY `governance_meetings_minutes_signed_by_foreign` (`minutes_signed_by`),
  KEY `governance_meetings_created_by_foreign` (`created_by`),
  KEY `governance_meetings_meeting_type_status_index` (`meeting_type`,`status`),
  KEY `governance_meetings_scheduled_at_status_index` (`scheduled_at`,`status`),
  KEY `governance_meetings_status_index` (`status`),
  CONSTRAINT `governance_meetings_board_committee_id_foreign` FOREIGN KEY (`board_committee_id`) REFERENCES `board_committees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `governance_meetings_chair_id_foreign` FOREIGN KEY (`chair_id`) REFERENCES `board_members` (`id`) ON DELETE SET NULL,
  CONSTRAINT `governance_meetings_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `governance_meetings_minutes_approved_by_foreign` FOREIGN KEY (`minutes_approved_by`) REFERENCES `board_members` (`id`) ON DELETE SET NULL,
  CONSTRAINT `governance_meetings_minutes_signed_by_foreign` FOREIGN KEY (`minutes_signed_by`) REFERENCES `board_members` (`id`) ON DELETE SET NULL,
  CONSTRAINT `governance_meetings_secretary_id_foreign` FOREIGN KEY (`secretary_id`) REFERENCES `board_members` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `governance_policies`;
CREATE TABLE `governance_policies` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `policy_code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `purpose` text COLLATE utf8mb4_unicode_ci,
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `version_number` int unsigned NOT NULL DEFAULT '1',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `approval_resolution_id` bigint unsigned DEFAULT NULL,
  `owner_id` bigint unsigned NOT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `effective_from` date DEFAULT NULL,
  `review_due` date DEFAULT NULL,
  `next_review_date` date DEFAULT NULL,
  `supersedes_policy_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `governance_policies_policy_code_unique` (`policy_code`),
  KEY `governance_policies_approval_resolution_id_foreign` (`approval_resolution_id`),
  KEY `governance_policies_owner_id_foreign` (`owner_id`),
  KEY `governance_policies_approved_by_foreign` (`approved_by`),
  KEY `governance_policies_created_by_foreign` (`created_by`),
  KEY `governance_policies_category_status_index` (`category`,`status`),
  KEY `governance_policies_status_index` (`status`),
  KEY `governance_policies_supersedes_policy_id_foreign` (`supersedes_policy_id`),
  CONSTRAINT `governance_policies_approval_resolution_id_foreign` FOREIGN KEY (`approval_resolution_id`) REFERENCES `resolutions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `governance_policies_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `governance_policies_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `governance_policies_owner_id_foreign` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`),
  CONSTRAINT `governance_policies_supersedes_policy_id_foreign` FOREIGN KEY (`supersedes_policy_id`) REFERENCES `governance_policies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `hazardous_substances`;
CREATE TABLE `hazardous_substances` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
