  `hazard_statements` text COLLATE utf8mb4_unicode_ci,
  `precautionary_statements` text COLLATE utf8mb4_unicode_ci,
  `physical_form` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `first_aid_measures` text COLLATE utf8mb4_unicode_ci,
  `firefighting_measures` text COLLATE utf8mb4_unicode_ci,
  `spill_procedures` text COLLATE utf8mb4_unicode_ci,
  `handling_precautions` text COLLATE utf8mb4_unicode_ci,
  `storage_requirements` text COLLATE utf8mb4_unicode_ci,
