  `running_balance` decimal(12,2) NOT NULL,
  `entry_date` date NOT NULL,
  `recorded_by` bigint unsigned NOT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `attachments` json DEFAULT NULL,
  `journal_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `house_ledger_entries_house_ledger_id_foreign` (`house_ledger_id`),
  KEY `house_ledger_entries_recorded_by_foreign` (`recorded_by`),
  KEY `house_ledger_entries_approved_by_foreign` (`approved_by`),
  KEY `house_ledger_entries_tenant_id_index` (`tenant_id`),
  KEY `house_ledger_entries_journal_id_foreign` (`journal_id`),
  CONSTRAINT `house_ledger_entries_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `house_ledger_entries_house_ledger_id_foreign` FOREIGN KEY (`house_ledger_id`) REFERENCES `house_ledgers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `house_ledger_entries_journal_id_foreign` FOREIGN KEY (`journal_id`) REFERENCES `fin_journals` (`id`) ON DELETE SET NULL,
  CONSTRAINT `house_ledger_entries_recorded_by_foreign` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

