  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `incident_followups_created_by_foreign` (`created_by`),
  KEY `incident_followups_client_incident_id_completed_at_index` (`client_incident_id`,`completed_at`),
  KEY `incident_followups_assigned_to_user_id_due_at_index` (`assigned_to_user_id`,`due_at`),
  CONSTRAINT `incident_followups_assigned_to_user_id_foreign` FOREIGN KEY (`assigned_to_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `incident_followups_client_incident_id_foreign` FOREIGN KEY (`client_incident_id`) REFERENCES `client_incidents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `incident_followups_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `incident_governance_escalations`;
CREATE TABLE `incident_governance_escalations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `client_incident_id` bigint unsigned NOT NULL,
  `notifiable_incident_id` bigint unsigned DEFAULT NULL,
  `risk_register_entry_id` bigint unsigned DEFAULT NULL,
  `escalation_reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `notified_chair` bigint unsigned DEFAULT NULL,
  `notified_ceo` bigint unsigned DEFAULT NULL,
  `chair_notified_at` timestamp NULL DEFAULT NULL,
  `ceo_notified_at` timestamp NULL DEFAULT NULL,
  `acknowledged_at` timestamp NULL DEFAULT NULL,
  `acknowledged_by` bigint unsigned DEFAULT NULL,
