  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `incident_governance_escalations_notifiable_incident_id_foreign` (`notifiable_incident_id`),
  KEY `incident_governance_escalations_risk_register_entry_id_foreign` (`risk_register_entry_id`),
  KEY `incident_governance_escalations_notified_chair_foreign` (`notified_chair`),
  KEY `incident_governance_escalations_notified_ceo_foreign` (`notified_ceo`),
  KEY `incident_governance_escalations_acknowledged_by_foreign` (`acknowledged_by`),
  KEY `incident_governance_escalations_status_index` (`status`),
  CONSTRAINT `incident_governance_escalations_acknowledged_by_foreign` FOREIGN KEY (`acknowledged_by`) REFERENCES `users` (`id`),
  CONSTRAINT `incident_governance_escalations_notifiable_incident_id_foreign` FOREIGN KEY (`notifiable_incident_id`) REFERENCES `notifiable_incidents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `incident_governance_escalations_notified_ceo_foreign` FOREIGN KEY (`notified_ceo`) REFERENCES `users` (`id`),
  CONSTRAINT `incident_governance_escalations_notified_chair_foreign` FOREIGN KEY (`notified_chair`) REFERENCES `users` (`id`),
  CONSTRAINT `incident_governance_escalations_risk_register_entry_id_foreign` FOREIGN KEY (`risk_register_entry_id`) REFERENCES `risk_register_entries` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `incident_templates`;
CREATE TABLE `incident_templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `severity` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `default_description` text COLLATE utf8mb4_unicode_ci,
  `prompts` json DEFAULT NULL,
  `checklist` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `incident_templates_name_index` (`name`),
  KEY `incident_templates_type_index` (`type`),
  KEY `incident_templates_severity_index` (`severity`),
  KEY `incident_templates_is_active_index` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integration_alerts`;
CREATE TABLE `integration_alerts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `site_id` bigint unsigned NOT NULL,
  `room_id` bigint unsigned DEFAULT NULL,
  `hardware_id` bigint unsigned DEFAULT NULL,
  `integration_event_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `severity` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'new',
  `assigned_to_user_id` bigint unsigned DEFAULT NULL,
  `acknowledged_at` datetime DEFAULT NULL,
  `acknowledged_by_user_id` bigint unsigned DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `closed_by_user_id` bigint unsigned DEFAULT NULL,
  `close_reason` text COLLATE utf8mb4_unicode_ci,
  `incident_id` bigint unsigned DEFAULT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_event_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `meta` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `integration_alerts_room_id_foreign` (`room_id`),
  KEY `integration_alerts_hardware_id_foreign` (`hardware_id`),
  KEY `integration_alerts_integration_event_id_foreign` (`integration_event_id`),
  KEY `integration_alerts_assigned_to_user_id_foreign` (`assigned_to_user_id`),
  KEY `integration_alerts_acknowledged_by_user_id_foreign` (`acknowledged_by_user_id`),
  KEY `integration_alerts_closed_by_user_id_foreign` (`closed_by_user_id`),
  KEY `integration_alerts_tenant_id_status_severity_index` (`tenant_id`,`status`,`severity`),
  KEY `integration_alerts_site_id_status_index` (`site_id`,`status`),
  KEY `integration_alerts_tenant_id_index` (`tenant_id`),
  CONSTRAINT `integration_alerts_acknowledged_by_user_id_foreign` FOREIGN KEY (`acknowledged_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_alerts_assigned_to_user_id_foreign` FOREIGN KEY (`assigned_to_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_alerts_closed_by_user_id_foreign` FOREIGN KEY (`closed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_alerts_hardware_id_foreign` FOREIGN KEY (`hardware_id`) REFERENCES `location_hardware` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_alerts_integration_event_id_foreign` FOREIGN KEY (`integration_event_id`) REFERENCES `integration_events` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_alerts_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `site_rooms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_alerts_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integration_events`;
CREATE TABLE `integration_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `site_id` bigint unsigned NOT NULL,
  `room_id` bigint unsigned DEFAULT NULL,
  `hardware_id` bigint unsigned DEFAULT NULL,
  `canonical_device_id` bigint unsigned DEFAULT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_app` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_event_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occurred_at` datetime NOT NULL,
  `received_at` datetime NOT NULL,
  `severity` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info',
  `event_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tags` json DEFAULT NULL,
  `normalized_payload` json DEFAULT NULL,
  `raw_payload` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integration_events_provider_source_event_id_unique` (`provider`,`source_event_id`),
  KEY `integration_events_site_id_foreign` (`site_id`),
  KEY `integration_events_room_id_foreign` (`room_id`),
  KEY `integration_events_hardware_id_foreign` (`hardware_id`),
  KEY `integration_events_tenant_id_site_id_occurred_at_index` (`tenant_id`,`site_id`,`occurred_at`),
  KEY `integration_events_severity_occurred_at_index` (`severity`,`occurred_at`),
  KEY `integration_events_tenant_id_index` (`tenant_id`),
  KEY `integration_events_canonical_created_idx` (`canonical_device_id`,`created_at`),
  CONSTRAINT `integration_events_canonical_device_id_foreign` FOREIGN KEY (`canonical_device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_events_hardware_id_foreign` FOREIGN KEY (`hardware_id`) REFERENCES `location_hardware` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_events_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `site_rooms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `integration_events_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integration_site_configs`;
CREATE TABLE `integration_site_configs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `site_id` bigint unsigned NOT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tenant_only',
  `mapped_external_site_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mapped_external_site_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `overrides` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integration_site_configs_site_id_provider_unique` (`site_id`,`provider`),
  KEY `integration_site_configs_tenant_id_index` (`tenant_id`),
  CONSTRAINT `integration_site_configs_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integration_site_secrets`;
CREATE TABLE `integration_site_secrets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `site_id` bigint unsigned NOT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `capability` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secret_encrypted` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `last_tested_at` datetime DEFAULT NULL,
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integration_site_secrets_site_id_provider_capability_unique` (`site_id`,`provider`,`capability`),
  KEY `integration_site_secrets_tenant_id_index` (`tenant_id`),
  CONSTRAINT `integration_site_secrets_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integration_sync_logs`;
CREATE TABLE `integration_sync_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `site_id` bigint unsigned DEFAULT NULL,
  `action` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'started',
  `items_processed` int unsigned NOT NULL DEFAULT '0',
  `items_created` int unsigned NOT NULL DEFAULT '0',
  `items_updated` int unsigned NOT NULL DEFAULT '0',
  `items_errored` int unsigned NOT NULL DEFAULT '0',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `started_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `integration_sync_logs_site_id_foreign` (`site_id`),
  KEY `integration_sync_logs_tenant_id_provider_index` (`tenant_id`,`provider`),
  KEY `integration_sync_logs_tenant_id_index` (`tenant_id`),
  CONSTRAINT `integration_sync_logs_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integration_tenant_secrets`;
CREATE TABLE `integration_tenant_secrets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `secret_encrypted` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `secret_last4` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'disconnected',
  `last_tested_at` datetime DEFAULT NULL,
  `last_synced_at` datetime DEFAULT NULL,
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `config` json DEFAULT NULL,
  `rotated_at` datetime DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integration_tenant_secrets_tenant_id_provider_unique` (`tenant_id`,`provider`),
  KEY `integration_tenant_secrets_created_by_foreign` (`created_by`),
  KEY `integration_tenant_secrets_tenant_id_index` (`tenant_id`),
  CONSTRAINT `integration_tenant_secrets_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `integrations`;
CREATE TABLE `integrations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `provider` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'inactive',
  `last_tested_at` datetime DEFAULT NULL,
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `capabilities` json DEFAULT NULL,
  `config` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `integrations_tenant_id_provider_unique` (`tenant_id`,`provider`),
  KEY `integrations_tenant_id_index` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `invoice_items`;
CREATE TABLE `invoice_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `invoice_id` bigint unsigned NOT NULL,
  `billing_entry_id` bigint unsigned DEFAULT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` decimal(10,2) NOT NULL,
  `unit_price` decimal(8,2) NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `service_date` date DEFAULT NULL,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `invoice_items_invoice_id_foreign` (`invoice_id`),
  KEY `invoice_items_organization_id_index` (`organization_id`),
  CONSTRAINT `invoice_items_invoice_id_foreign` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `invoices`;
CREATE TABLE `invoices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `client_id` bigint unsigned DEFAULT NULL,
  `funding_body` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invoice_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `issue_date` date NOT NULL,
  `due_date` date DEFAULT NULL,
  `paid_date` date DEFAULT NULL,
  `subtotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `tax_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `journal_id` bigint unsigned DEFAULT NULL,
  `gl_posted_at` datetime DEFAULT NULL,
  `payment_terms` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `invoices_client_id_foreign` (`client_id`),
  KEY `invoices_created_by_foreign` (`created_by`),
  KEY `invoices_invoice_number_index` (`invoice_number`),
  KEY `invoices_status_index` (`status`),
  KEY `invoices_due_date_index` (`due_date`),
  KEY `invoices_organization_id_index` (`organization_id`),
  KEY `invoices_journal_id_index` (`journal_id`),
  CONSTRAINT `invoices_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `invoices_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_jobs` int NOT NULL,
  `pending_jobs` int NOT NULL,
  `failed_jobs` int NOT NULL,
  `failed_job_ids` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` mediumtext COLLATE utf8mb4_unicode_ci,
  `cancelled_at` int DEFAULT NULL,
  `created_at` int NOT NULL,
  `finished_at` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `queue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` tinyint unsigned NOT NULL,
  `reserved_at` int unsigned DEFAULT NULL,
  `available_at` int unsigned NOT NULL,
  `created_at` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `jobs_queue_index` (`queue`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `legal_holds`;
CREATE TABLE `legal_holds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `hold_reference` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hold_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `holdable_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `holdable_id` bigint unsigned DEFAULT NULL,
  `related_records` json DEFAULT NULL,
  `status` enum('active','released') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `imposed_at` timestamp NOT NULL,
  `imposed_by_user_id` bigint unsigned DEFAULT NULL,
  `released_at` timestamp NULL DEFAULT NULL,
  `released_by_user_id` bigint unsigned DEFAULT NULL,
  `release_reason` text COLLATE utf8mb4_unicode_ci,
  `review_date` date DEFAULT NULL,
  `legal_authority` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `legal_holds_hold_reference_unique` (`hold_reference`),
  KEY `legal_holds_holdable_type_holdable_id_index` (`holdable_type`,`holdable_id`),
