  `target_score` decimal(3,1) NOT NULL DEFAULT '3.0',
  `actual_score` decimal(3,1) DEFAULT NULL,
  `self_assessment` text COLLATE utf8mb4_unicode_ci,
  `board_assessment` text COLLATE utf8mb4_unicode_ci,
  `evidence_links` json DEFAULT NULL,
  `evidence_summary` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'not_started',
