  `period_end` date NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'drafting',
  `overall_rating` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `overall_assessment` text COLLATE utf8mb4_unicode_ci,
