  UNIQUE KEY `performance_reviews_reviewee_id_review_cycle_unique` (`reviewee_id`,`review_cycle`),
  KEY `performance_reviews_approval_resolution_id_foreign` (`approval_resolution_id`),
  KEY `performance_reviews_created_by_foreign` (`created_by`),
  KEY `performance_reviews_reviewee_id_review_cycle_index` (`reviewee_id`,`review_cycle`),
  KEY `performance_reviews_status_period_end_index` (`status`,`period_end`),
  CONSTRAINT `performance_reviews_approval_resolution_id_foreign` FOREIGN KEY (`approval_resolution_id`) REFERENCES `resolutions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `performance_reviews_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `performance_reviews_reviewee_id_foreign` FOREIGN KEY (`reviewee_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

