CREATE TABLE `privacy_impact_assessments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `assessment_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_or_process` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `assessment_type` enum('new_project','process_change','system_upgrade','periodic_review') COLLATE utf8mb4_unicode_ci NOT NULL,
  `assessor_id` bigint unsigned DEFAULT NULL,
  `assessment_date` timestamp NOT NULL,
  `personal_data_types` json DEFAULT NULL,
  `data_subjects` json DEFAULT NULL,
  `processing_purpose` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `legal_basis` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `identified_risks` json DEFAULT NULL,
  `overall_risk_level` enum('low','medium','high','very_high') COLLATE utf8mb4_unicode_ci NOT NULL,
  `mitigation_measures` json DEFAULT NULL,
  `residual_risk_level` enum('low','medium','high','very_high') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `outcome` enum('approved','approved_with_conditions','rejected','requires_dpo_review') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_by_user_id` bigint unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `review_date` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `privacy_impact_assessments_assessor_id_foreign` (`assessor_id`),
  KEY `privacy_impact_assessments_approved_by_user_id_foreign` (`approved_by_user_id`),
  KEY `pia_risk_date_idx` (`overall_risk_level`,`assessment_date`),
  KEY `privacy_impact_assessments_review_date_index` (`review_date`),
  CONSTRAINT `privacy_impact_assessments_approved_by_user_id_foreign` FOREIGN KEY (`approved_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
