  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `clock_in_latitude` decimal(10,7) DEFAULT NULL,
  `clock_in_longitude` decimal(10,7) DEFAULT NULL,
  `clock_out_latitude` decimal(10,7) DEFAULT NULL,
  `clock_out_longitude` decimal(10,7) DEFAULT NULL,
  `clock_in_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clock_out_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `geofence_verified` tinyint(1) DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `is_group_shift` tinyint(1) NOT NULL DEFAULT '0',
  `max_clients` tinyint unsigned DEFAULT NULL,
  `organization_id` bigint unsigned DEFAULT '1',
  `roster_period_id` bigint unsigned DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `publish_dirty_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shifts_started_by_foreign` (`started_by`),
  KEY `shifts_completed_by_foreign` (`completed_by`),
  KEY `shifts_created_by_foreign` (`created_by`),
  KEY `shifts_user_id_starts_at_index` (`user_id`,`starts_at`),
  KEY `shifts_client_id_starts_at_index` (`client_id`,`starts_at`),
  KEY `shifts_status_actual_starts_at_index` (`status`,`actual_starts_at`),
  KEY `shifts_status_index` (`status`),
  KEY `shifts_shift_series_id_starts_at_index` (`shift_series_id`,`starts_at`),
  KEY `shifts_service_context_id_foreign` (`service_context_id`),
  KEY `idx_shifts_client_starts` (`client_id`,`starts_at`),
  KEY `idx_shifts_user_starts` (`user_id`,`starts_at`),
  KEY `idx_shifts_status_starts` (`status`,`starts_at`),
  KEY `idx_shifts_respite_booking` (`respite_booking_id`),
  KEY `shifts_site_starts_idx` (`site_id`,`starts_at`),
  KEY `shifts_handover_waived_by_foreign` (`handover_waived_by`),
  KEY `shifts_organization_id_index` (`organization_id`),
  KEY `shifts_roster_period_id_foreign` (`roster_period_id`),
  KEY `shifts_published_at_index` (`published_at`),
  KEY `shifts_publish_dirty_at_index` (`publish_dirty_at`),
  CONSTRAINT `shifts_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `shifts_completed_by_foreign` FOREIGN KEY (`completed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_handover_waived_by_foreign` FOREIGN KEY (`handover_waived_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_respite_booking_id_foreign` FOREIGN KEY (`respite_booking_id`) REFERENCES `respite_bookings` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_roster_period_id_foreign` FOREIGN KEY (`roster_period_id`) REFERENCES `roster_periods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_service_context_id_foreign` FOREIGN KEY (`service_context_id`) REFERENCES `service_contexts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_shift_series_id_foreign` FOREIGN KEY (`shift_series_id`) REFERENCES `shift_series` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_started_by_foreign` FOREIGN KEY (`started_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `shifts_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=9302 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

