  KEY `site_damages_tenant_id_index` (`tenant_id`),
  CONSTRAINT `site_damages_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`),
  CONSTRAINT `site_damages_checklist_run_id_foreign` FOREIGN KEY (`checklist_run_id`) REFERENCES `site_checklist_runs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `site_damages_repaired_by_foreign` FOREIGN KEY (`repaired_by`) REFERENCES `users` (`id`),
  CONSTRAINT `site_damages_reported_by_foreign` FOREIGN KEY (`reported_by`) REFERENCES `users` (`id`),
  CONSTRAINT `site_damages_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

