  `severity` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL,
  `likelihood` enum('rare','unlikely','possible','likely','almost_certain') COLLATE utf8mb4_unicode_ci NOT NULL,
  `risk_rating` enum('low','medium','high','extreme') COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `photo_paths` json DEFAULT NULL,
  `immediate_action_taken` text COLLATE utf8mb4_unicode_ci,
  `immediate_action_applied` tinyint(1) NOT NULL DEFAULT '0',
  `control_hierarchy` json DEFAULT NULL,
  `residual_risk_rating` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `residual_likelihood` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `residual_severity` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `control_effectiveness` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `control_review_date` date DEFAULT NULL,
  `reported_by_user_id` bigint unsigned NOT NULL,
  `assigned_to_user_id` bigint unsigned DEFAULT NULL,
  `assigned_at` timestamp NULL DEFAULT NULL,
  `status` enum('open','in_progress','mitigated','closed','reopened') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `status_changed_at` timestamp NULL DEFAULT NULL,
  `status_changed_by_user_id` bigint unsigned DEFAULT NULL,
  `resolution_summary` text COLLATE utf8mb4_unicode_ci,
  `resolution_evidence` json DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
