  KEY `site_hazards_reported_by_user_id_foreign` (`reported_by_user_id`),
  KEY `site_hazards_status_changed_by_user_id_foreign` (`status_changed_by_user_id`),
  KEY `site_hazards_closed_by_user_id_foreign` (`closed_by_user_id`),
  KEY `site_hazards_site_id_status_severity_index` (`site_id`,`status`,`severity`),
  KEY `site_hazards_assigned_to_user_id_status_index` (`assigned_to_user_id`,`status`),
  KEY `site_hazards_due_date_status_index` (`due_date`,`status`),
  KEY `site_hazards_tenant_id_index` (`tenant_id`),
  KEY `site_hazards_hazard_type_index` (`hazard_type`),
  KEY `site_hazards_severity_index` (`severity`),
  KEY `site_hazards_risk_rating_index` (`risk_rating`),
  KEY `site_hazards_status_index` (`status`),
  KEY `site_hazards_due_date_index` (`due_date`),
  CONSTRAINT `site_hazards_assigned_to_user_id_foreign` FOREIGN KEY (`assigned_to_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `site_hazards_closed_by_user_id_foreign` FOREIGN KEY (`closed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `site_hazards_reported_by_user_id_foreign` FOREIGN KEY (`reported_by_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `site_hazards_site_id_foreign` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE,
  CONSTRAINT `site_hazards_status_changed_by_user_id_foreign` FOREIGN KEY (`status_changed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

